def solve_convex_weights(
    target,
    donor_matrix,
    selected_cols=None,
):

    target = np.asarray(target, dtype=float)
    donor_matrix = np.asarray(donor_matrix, dtype=float)

    if selected_cols is None:
        selected_cols = list(
            range(donor_matrix.shape[1])
        )

    X = donor_matrix[:, selected_cols]
    J = X.shape[1]

    if J == 0:
        raise ValueError("No donor columns supplied.")

    if J == 1:
        w = np.array([1.0])
        mse = float(
            np.mean(
                (target - X[:, 0]) ** 2
            )
        )
        return w, mse

    x0 = np.full(
        J,
        1.0 / J,
    )

    def objective(w):
        return float(
            np.mean(
                (target - X @ w) ** 2
            )
        )

    result = minimize(
        objective,
        x0,
        method="SLSQP",
        bounds=[(0.0, 1.0)] * J,
        constraints={
            "type": "eq",
            "fun": lambda w: w.sum() - 1.0,
        },
        options={
            "ftol": OPT_TOL,
            "maxiter": OPT_MAXITER,
        },
    )

    if not result.success:
        raise RuntimeError(
            f"SLSQP failed: {result.message}"
        )

    w = np.asarray(
        result.x,
        dtype=float,
    )

    # Clean tiny numerical values and renormalize.
    w[np.abs(w) < 1e-12] = 0.0

    if w.sum() <= 0:
        raise RuntimeError(
            "Estimated weights sum to zero."
        )

    w = w / w.sum()

    return w, objective(w)

